{
  "definition_simple": "指可以随身携带、随时随地上网或处理信息的便携式电子产品，如智能手机和平板电脑。",
  "definition_standard": "具备移动计算能力、无线通信功能及人机交互界面的便携式电子终端设备的统称，主要涵盖智能手机、平板电脑及可穿戴智能设备等。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "请在飞机起飞前关闭您的行动装置。"
    },
    {
      "tier": "T1",
      "sentence": "走路时一直看行动装置是非常危险的行为。"
    },
    {
      "tier": "T2",
      "sentence": "许多长辈也开始学习如何使用行动装置与家人视频通话。"
    },
    {
      "tier": "T2",
      "sentence": "出差期间，我习惯只携带轻便的行动装置来处理日常电子邮件。"
    },
    {
      "tier": "T3",
      "sentence": "这家图书馆提供高速无线网络，方便读者使用行动装置查阅电子资源。"
    },
    {
      "tier": "T3",
      "sentence": "长时间以不良姿势操作行动装置，极易引发颈椎僵硬和视力疲劳。"
    },
    {
      "tier": "T4",
      "sentence": "随着行动装置的普及，移动支付已逐渐融入大众的日常生活。"
    },
    {
      "tier": "T4",
      "sentence": "该云端平台支持多平台同步，让使用者能在不同的行动装置间无缝切换工作任务。"
    },
    {
      "tier": "T5",
      "sentence": "面对市场上规格繁杂的行动装置，前端工程师必须采用响应式设计以确保网页正常显示。"
    },
    {
      "tier": "T6",
      "sentence": "针对行动装置端点展开的高级持续性威胁，企业应构建严密的零信任安全架构以防范敏感数据外泄。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "行动壮志",
      "explanation": "“壮志”（zhuàngzhì）与“装置”（zhuāngzhì）读音高度相近，但“行动壮志”指付诸实践的宏大志向，属于字音相近导致的词义混淆。"
    },
    {
      "word": "震动装置",
      "explanation": "“震动”（zhèndòng）与“行动”（xíngdòng）发音部分相似，容易在语音不清时误听，但指产生物理振动的机械零部件。"
    },
    {
      "word": "移动装置",
      "explanation": "“移动”（yídòng）与“行动”（xíngdòng）同义且韵母相近，快速语流中容易发音或辨听混淆，属于两岸不同用词习惯下的近音近义词。"
    }
  ],
  "primary_collocate": "普及",
  "collocation_distractors": [
    {
      "word": "行走",
      "explanation": "“行走”仅表示人或动物用脚步行，不能与“装置”组合来表示可以随身携带的智能设备。"
    },
    {
      "word": "敏捷",
      "explanation": "“敏捷”常形容动作或思维反应快速，不能直接修饰“行动装置”来表达硬件设备运行流畅。"
    },
    {
      "word": "随身",
      "explanation": "“随身”常作副词或定语修饰动词行为（如“随身携带”），直接构成“随身行动装置”属于语义重复的冗余搭配。"
    }
  ],
  "collocation_wrong_collocate": "驾驶",
  "cloze_distractors": [
    {
      "word": "不动产",
      "explanation": "词义完全不同，“不动产”指土地与房屋等不可移动资产，不能用于指代便携电子产品。"
    },
    {
      "word": "交通工具",
      "explanation": "范畴混淆，“交通工具”用于载人运输，虽然具备“移动性”，但不是信息处理终端。"
    },
    {
      "word": "应急预案",
      "explanation": "语域无关，“应急预案”属于行政与管理策略术语，与硬件设备毫无关联。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "工人们在码头使用重型行动装置吊运集装箱。",
      "explanation": "范畴错误。“行动装置”在现代汉语中专指手机、平板等便携式数字化信息终端，不能用于指代起重机、吊车等工业重型机械。"
    },
    {
      "sentence": "请在早高峰期间谨慎驾驶您的行动装置，避免发生交通事故。",
      "explanation": "动宾搭配不当。“行动装置”是手持电子设备而非车辆等交通工具，不能与动词“驾驶”搭配。"
    },
    {
      "sentence": "为了防止小偷逃跑，警方在小巷口启动了行动装置阻挡行人通行。",
      "explanation": "字面解构错误。误将“行动”理解为“走动的行为”，把“行动装置”错当作限制人员行动的机关设施。"
    }
  ],
  "spot_incorrect": {
    "sentence": "随着数位时代的来临，行动装置的渗透率大幅提高，但部分年长者依然很难驾驶这些设备。",
    "error_description": "动词“驾驶”只能搭配车辆、飞机、船只等交通运输工具，操作手机等“行动装置”应使用“操作”或“使用”。",
    "corrected": "随着数位时代的来临，行动装置的渗透率大幅提高，但部分年长者依然很难操作这些设备。"
  },
  "word_family_forms": [
    "行动化",
    "行动端"
  ],
  "word_family_fake_forms": [
    "装置化",
    "行动装",
    "行动装置性"
  ],
  "syn_ant_candidates": [
    {
      "word": "移动设备",
      "relation": "synonym"
    },
    {
      "word": "手持设备",
      "relation": "synonym"
    },
    {
      "word": "固定终端",
      "relation": "antonym"
    },
    {
      "word": "台式电脑",
      "relation": "antonym"
    }
  ],
